<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ChatLineRound, Delete, Edit, Plus, Search, Star, StarFilled } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { workbenchApi, workbenchMessage } from '../api'
import type { Prompt, PromptInput } from '../types'

const router = useRouter(); const loading = ref(true); const saving = ref(false); const search = ref(''); const prompts = ref<Prompt[]>([]); const dialog = ref(false); const editing = ref('')
const form = reactive<PromptInput>({ title: '', description: '', category: '', content: '', favorite: false })
async function load() { loading.value = true; try { prompts.value = await workbenchApi.prompts(search.value) } catch (error) { ElMessage.error(workbenchMessage(error, '提示词加载失败')) } finally { loading.value = false } }
function create() { editing.value = ''; Object.assign(form, { title: '', description: '', category: '', content: '', favorite: false }); dialog.value = true }
function edit(item: Prompt) { editing.value = item.id; Object.assign(form, { title: item.title, description: item.description, category: item.category, content: item.content, favorite: item.favorite }); dialog.value = true }
async function save() { if (!form.title.trim() || !form.content.trim()) { ElMessage.warning('标题和内容不能为空'); return }; saving.value = true; try { editing.value ? await workbenchApi.updatePrompt(editing.value, { ...form }) : await workbenchApi.createPrompt({ ...form }); dialog.value = false; ElMessage.success('提示词已保存'); await load() } catch (error) { ElMessage.error(workbenchMessage(error, '保存失败')) } finally { saving.value = false } }
async function favorite(item: Prompt) { await workbenchApi.updatePrompt(item.id, { title: item.title, description: item.description, category: item.category, content: item.content, favorite: !item.favorite }); await load() }
async function use(item: Prompt) { await workbenchApi.usePrompt(item.id); await router.push({ path: '/ai-workbench/chat', query: { prompt: item.content } }) }
async function remove(item: Prompt) { try { await ElMessageBox.confirm(`确定删除“${item.title}”吗？`, '删除提示词', { type: 'warning' }); await workbenchApi.deletePrompt(item.id); await load() } catch (error) { if (error !== 'cancel' && error !== 'close') ElMessage.error(workbenchMessage(error, '删除失败')) } }
onMounted(load)
</script>

<template><div class="page-stack ai-page"><header class="page-heading"><div><h2>我的提示词</h2><p>沉淀可复用的工作方法</p></div><el-button type="primary" :icon="Plus" @click="create">新建提示词</el-button></header><div class="ai-prompt-filter"><el-input v-model="search" :prefix-icon="Search" clearable placeholder="搜索提示词" @keyup.enter="load" @clear="load" /><el-button @click="load">搜索</el-button></div><section v-loading="loading" class="ai-prompt-grid"><article v-for="item in prompts" :key="item.id"><header><el-tag v-if="item.category" effect="plain">{{ item.category }}</el-tag><el-button text :icon="item.favorite ? StarFilled : Star" :class="{ favorite: item.favorite }" aria-label="收藏" @click="favorite(item)" /></header><h3>{{ item.title }}</h3><p>{{ item.description || item.content }}</p><pre>{{ item.content }}</pre><footer><small>使用 {{ item.useCount }} 次</small><span><el-button text :icon="Edit" aria-label="编辑" @click="edit(item)" /><el-button text type="danger" :icon="Delete" aria-label="删除" @click="remove(item)" /><el-button type="primary" plain :icon="ChatLineRound" @click="use(item)">用于对话</el-button></span></footer></article></section><el-empty v-if="!loading && !prompts.length" description="还没有提示词" /><el-dialog v-model="dialog" :title="editing ? '编辑提示词' : '新建提示词'" width="min(620px, 94vw)"><el-form label-position="top"><div class="form-grid"><el-form-item label="标题"><el-input v-model="form.title" maxlength="120" /></el-form-item><el-form-item label="分类"><el-input v-model="form.category" maxlength="60" /></el-form-item></div><el-form-item label="描述"><el-input v-model="form.description" maxlength="300" /></el-form-item><el-form-item label="提示词内容"><el-input v-model="form.content" type="textarea" :rows="9" maxlength="20000" show-word-limit /></el-form-item><el-checkbox v-model="form.favorite">加入收藏</el-checkbox></el-form><template #footer><el-button @click="dialog = false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog></div></template>

<style scoped>
.ai-prompt-filter{display:flex;gap:8px;width:min(520px,100%)}.ai-prompt-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.ai-prompt-grid article{display:flex;flex-direction:column;min-height:280px;padding:17px;background:var(--surface);border:1px solid var(--line);border-radius:6px}.ai-prompt-grid header,.ai-prompt-grid footer{display:flex;align-items:center;justify-content:space-between;gap:8px}.favorite{color:#b57c16}.ai-prompt-grid h3{margin-top:13px;font-size:15px}.ai-prompt-grid>article>p{display:-webkit-box;overflow:hidden;margin-top:7px;color:var(--muted);font-size:12px;line-height:1.5;-webkit-box-orient:vertical;-webkit-line-clamp:2}.ai-prompt-grid pre{flex:1;overflow:hidden;max-height:90px;margin:12px 0;padding:10px;color:var(--ink);background:var(--theme-table-header);border-radius:5px;font:12px/1.5 "SFMono-Regular",Consolas,monospace;white-space:pre-wrap}.ai-prompt-grid small{color:var(--muted)}.ai-prompt-grid footer span{display:flex}@media(max-width:1000px){.ai-prompt-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.ai-prompt-grid{grid-template-columns:1fr}}
</style>
